noten = {"Mathe": 2, "Deutsch": 1, "POS": 3}
with open("noten.txt", "w", encoding="utf-8") as datei:
    for fach, note in noten.items():
        datei.write(f"{fach};{note}\n")

summe = 0
with open("noten.txt", encoding="utf-8") as datei:
    for zeile in datei:
        fach, note = zeile.strip().split(";")
        summe += int(note)
print(f"Notensumme: {summe}")   # 6

try:
    with open("highscore.txt", encoding="utf-8") as datei:
        highscore = int(datei.read())
except FileNotFoundError:
    highscore = 0
print(f"Highscore: {highscore}")
